<?php /* VIVA NOTE: One booking detail page; state-specific action forms submit the CSRF token. */ ?><div class="toolbar"><p>Reservation details and landlord actions</p><a href="<?=e(url('/bookings'))?>">← All bookings</a></div>
<div class="detail-grid"><section class="panel"><div class="panel-title"><h3><?=e($booking['student_name'])?></h3><span class="status"><?=e(pill($booking['status']))?></span></div>
<dl class="details"><dt>Student email</dt><dd><?=e($booking['student_email'])?></dd><dt>Phone</dt><dd><?=e($booking['student_phone']?:'—')?></dd><dt>Property</dt><dd><?=e($booking['property_title'])?></dd><dt>Room</dt><dd><?=e($booking['room_label']?:'Room #'.$booking['room_id'])?></dd><dt>Slot</dt><dd>#<?=e($booking['slot_number'])?></dd><dt>Monthly rent</dt><dd><?=e(cash($booking['price']))?></dd><dt>Requested</dt><dd><?=e(date_label($booking['requested_at']))?></dd><dt>Moved in</dt><dd><?=e(date_label($booking['move_in_date']))?></dd><dt>Moved out</dt><dd><?=e(date_label($booking['move_out_date']))?></dd></dl></section>
<section class="panel"><h3>Manage reservation</h3><p>Actions follow a controlled status lifecycle. PHP transactions update slot availability and reservation records.</p>
<?php $actions=match($booking['status']){'pending'=>['accept'=>'Accept request','reject'=>'Reject request'],'accepted'=>['move_in'=>'Confirm move-in'],'active'=>['move_out'=>'Confirm move-out'],default=>[]};?>
<?php foreach($actions as $value=>$label):?><form method="post" action="<?=e(url('/booking/decide',['id'=>$booking['booking_id']]))?>" class="stack action-form" data-confirm="Confirm: <?=e($label)?>?"><?=csrf_field()?><input type="hidden" name="action" value="<?=e($value)?>"><?php if($value==='reject'):?><label>Reason (optional)<textarea name="reason" maxlength="1000" rows="2"></textarea></label><?php endif;?><button class="btn <?=$value==='reject'?'danger':''?>"><?=e($label)?></button></form><?php endforeach;?>
<?php if(!$actions):?><div class="alert info">No further landlord actions are available for this booking.</div><?php endif;?>
<form method="post" action="<?=e(url('/chat/start'))?>" class="form-actions"><?=csrf_field()?><input type="hidden" name="booking_id" value="<?=e($booking['booking_id'])?>"><button class="btn secondary">Message this student →</button></form>
<a class="btn secondary" href="<?=e(url('/complaint/new',['booking_id'=>$booking['booking_id']]))?>">File a complaint</a></section></div>
